CREATE TABLE IF NOT EXISTS t_p83915249_biotech_anime_store.ore_processing (id SERIAL PRIMARY KEY, planet_id INTEGER NOT NULL, player_id INTEGER NOT NULL, factory_level INTEGER NOT NULL DEFAULT 1, ore_input INTEGER NOT NULL DEFAULT 0, alloy_output INTEGER NOT NULL DEFAULT 0, components_output INTEGER NOT NULL DEFAULT 0, processing_speed INTEGER NOT NULL DEFAULT 10, last_processed_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());